<script setup>
import { computed, onActivated, onMounted, reactive, ref } from 'vue';
import homeHeader from '@/components/homeHeader.vue';
import { AuthService } from "@/api/home";
import { useRouter } from 'vue-router';
import { menuStore } from '@/store/menu';
const store = menuStore();
const router = useRouter();
const active = ref(0)
const tablist = ref([])
const loading = ref(false);
const finished = ref(false);
const homeData = ref();
const Banner = ref([])
const recommend = ref([])
const currentBackgroundImage = ref('');
const is_header = ref(false)
const changeSwipeAction = (item) => {
    currentBackgroundImage.value = Banner.value[item].src;
}
const pageInfo = reactive({
    page: 1,
    limit: 10,
    type_id: "",
    classify: 2,
})
const midindex = ref()
const leftList = ref([])
const rightList = ref([])

const currentBackgroundColor = ref('rgba(1,1,1,0)');
const changeColorAction = (op) => {
    currentBackgroundColor.value = `rgba(255,255,255,${op})`;
}
const getColNumber = () => {
    const length = Secondaryclassification.value.length;
    const rows = Math.ceil(length / 5);
    console.log(rows);
    return rows;
}
const getNineData = (num) => {
    const start = (num - 1) * 5;
    const end = num * 5;
    return Secondaryclassification.value.slice(start, end);
}

const secDataCol = ref(0);
const secDataItems = ref([]);

const ficationLoading = ref(false)
const indexdata = async () => {
    ficationLoading.value = true

    try {
        const res1 = await store.getmenuList();
        pageInfo.type_id = res1[0].id
        console.log(pageInfo.type_id)
        tablist.value = res1
        Secondaryclassification.value = []
        if (tablist.value[active.value].children) {
            Secondaryclassification.value = tablist.value[active.value].children
        }
        is_header.value = true
        ficationLoading.value = false
        secDataCol.value = getColNumber();
        const res = await AuthService.banner();
        Banner.value = res
        currentBackgroundImage.value = Banner.value[0].src;
    } catch (error) {
        is_header.value = true
        ficationLoading.value = false
    }
}
const grouplist = ref([[], []])
const onLoad = async (num) => {
    const res2 = await AuthService.prodect_list({ ...pageInfo })
    if (num == 1) {
        recommend.value = []
        grouplist.value = [[], []]
    }
    recommend.value = [...recommend.value, ...res2.dataList]
    grouplist.value = [[], []];
    recommend.value.forEach((item, index) => {
        grouplist.value[index % 2].push(item);
    });
    if (recommend.value.length < res2.total) {
        loading.value = false;
        pageInfo.page++;
    } else {
        finished.value = true;
    }
}
const Secondaryclassification = ref([])
const changTab = (e) => {
    Secondaryclassification.value = []
    pageInfo.type_id = null
    if (tablist.value[active.value].children) {
        Secondaryclassification.value = tablist.value[active.value].children
    }
    secDataCol.value = getColNumber();
    pageInfo.type_id = tablist.value[active.value].id
    finished.value = false
    pageInfo.page = 1
    onLoad(1);
}
onMounted(async () => {
    indexdata()
})
</script>
